// EXPORTS: EXERCISE_MEDIA, type ExerciseMedia
// 动作演示动图映射：由动作百科（https://fitness.xingshuwen.com）提供，素材版权归 Gym visual 所有
// key 为 exercises-db 中的动作 id。条目分两类，页面渲染必须区别对待：
//  1. 精确：仅 zh/gif/page 三项 —— 站上存在同名动作，直接用其演示动图；
//  2. 近似：approx: true + approxNote —— 站上无同名动作，取最接近的条目替代，
//     approxNote 写明「近似动作：XXX」，动作百科页与训练页必须显式标注「近似演示」，避免误导。
// 注：站上确无演示的 127 个动作已从动作库（exercises-db.json）中移除，故本表不再有「暂无」条目；
//     下方 none / searchName 字段保留为兜底标记，供后续新增缺口时使用。

export interface ExerciseMedia {
  /** 该动作在动作百科中的中文名（暂无演示的空缺条目为「站上暂无演示」，当前数据已无此情况） */
  zh: string;
  /** 演示动图直链（暂无演示条目为空） */
  gif?: string;
  /** 动作百科详情页（暂无演示条目为空） */
  page?: string;
  /** 近似演示：站上无同名动作，取最近条目替代 */
  approx?: boolean;
  /** 近似说明，如「近似动作：壶铃单臂高翻挺举」 */
  approxNote?: string;
  /** 站上暂无演示：详情页改为展示站内搜索入口 */
  none?: boolean;
  /** 站内搜索用的英文动作名 */
  searchName?: string;
}

